pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  var gs: List[List[Str]] = []
  for p in pairs {
    let a = p.get_or(0, "")
    let b = p.get_or(1, "")
    var merged: List[Str] = [a, b]
    var rest: List[List[Str]] = []
    for g in gs {
      if g.contains(a) or g.contains(b) {
        merged = merged.concat(g)
      } else {
        rest = rest.push(g)
      }
    }
    gs = rest.push(merged.unique())
  }
  let sorted_groups = gs.map(fn(grp) => grp.sort())
  return sorted_groups.sort_by(fn(grp) => grp.first().unwrap_or(""))
}
